local a={}function a.grid(b,c)c=c or{}local d=c.x0 or 1;local e=c.availW;local f=c.y0 or 1;local g=c.perRow or#b;local h=c.gap or 1;local i=c.align or"center"local j=c.pad or 0;local k=0;for l,m in ipairs(b)do if#m>k then k=#m end end;k=k+j;if g*k+(g-1)*h>e then h=0;if g*k>e then k=math.floor(e/g)end end;local n={}local o=1;local p=0;while o<=#b do local q=math.min(g,#b-o+1)local r=q*k+(q-1)*h;local s;if i=="center"then s=d+math.floor((e-r)/2)if s<d then s=d end else s=d end;for t=0,q-1 do n[#n+1]={x=s+t*(k+h),y=f+p,w=k}end;o=o+q;p=p+1 end;return n end;return a